<!-- Omit `styles`: the XML fragment parser cannot evaluate `style()`. -->
<Form>
  <TextField label="Name" placeholder="Enter your full name" description="Enter your full name" />
  <TextField label="Email" type="email" placeholder="Enter your email" description="Enter your email" />
  <Checkbox>I agree to the terms</Checkbox>
  <ButtonGroup>
    <Button type="submit" variant="primary">Submit</Button>
    <Button type="reset" variant="secondary">Reset</Button>
  </ButtonGroup>
</Form>

